+/** Picks a supported language (`en` or `ko`) from an `Accept-Language` header. */
+export function resolveLanguage(header, fallback = "en") {
+  if (typeof header !== "string" || !header.trim()) return fallback;
+  const candidates = [];
+  for (const part of header.split(",")) {
+    const [rawTag, ...params] = part.trim().split(";");
+    if (!rawTag) continue;
+    const base = rawTag.trim().toLowerCase().split(/[-_]/)[0];
+    if (!LANGUAGES.includes(base)) continue;
+    let q = 1;
+    let valid = true;
+    for (const param of params) {
+      const [k, v = ""] = param.split("=").map((s) => s.trim());
+      if (k && k.toLowerCase() === "q") {
+        const n = Number(v);
+        if (v === "" || Number.isNaN(n) || n < 0 || n > 1) valid = false;
+        else q = n;
+      }
+    }
+    if (valid && q > 0) candidates.push({ lang: base, q });
+  }
+  if (!candidates.length) return fallback;
+  candidates.sort((a, b) => b.q - a.q);
+  return candidates[0].lang;
+}
